def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        opp_c = sum(1 for a, b in history if b == 'C')
        return 'C' if opp_c * 2 >= n else 'D'
    opp_c = sum(1 for a, b in history if b == 'C')
    my_c = sum(1 for a, b in history if a == 'C')
    opp_d = n - opp_c
    if n < 6:
        return 'C' if history[-1][1] == 'C' else 'D'
    if opp_d <= 1:
        if n > 25 and n % 11 == 0 and rng.random() < 0.5:
            return 'D'
        return 'C'
    if opp_c <= 2:
        return 'D'
    recent = history[-10:]
    rc = sum(1 for a, b in recent if b == 'C')
    if rc == 0:
        if rng.random() < 0.06:
            return 'C'
        return 'D'
    if rc >= 8:
        return 'C'
    my_recent_d = sum(1 for a, b in recent if a == 'D')
    last_opp = history[-1][1]
    last_me = history[-1][0]
    rate = opp_c / n
    if rate > 0.6:
        if last_opp == 'D' and last_me == 'C' and rng.random() < 0.5:
            return 'D'
        return 'C'
    if rate > 0.35:
        if last_opp == 'D':
            return 'D' if rng.random() < 0.65 else 'C'
        return 'C'
    if last_opp == 'D' and last_me == 'D':
        if my_recent_d >= 4 and rng.random() < 0.55:
            return 'C'
        return 'D'
    if last_opp == 'D':
        if rng.random() < 0.12 + 0.2 * (rc / 10.0):
            return 'C'
        return 'D'
    if n % 13 == 12 and my_c > opp_c + 5:
        return 'D'
    return 'C'
